+  /// Updates this active autofill form with metadata from a newer framework
+  /// configuration without replacing the DOM form owned by this instance.
+  ///
+  /// A `TextInput.updateConfig` message creates a new [EngineAutofillForm]
+  /// while the current text input connection may still be using this form's
+  /// DOM elements and event listeners. Replacing the form object in that case
+  /// would disconnect the configuration from the live DOM form.
+  void updateFrameworkConfiguration(EngineAutofillForm configuration) {
+    assert(formIdentifier == configuration.formIdentifier);
+    assert(viewId == configuration.viewId);
+    assert(focusedElementId == configuration.focusedElementId);
+    assert(associateFocusedElementByAttribute == configuration.associateFocusedElementByAttribute);

